async function sendSms(g,text){const from=`+1555000000${g+2}`,uri=`http://127.0.0.1:${sms}${g===0?'/sms/incoming':'/sms/custom'}`,body=new URLSearchParams({From:from,Body:text});const signature=createHmac('sha1','mock-sms-token').update(uri+'Body'+text+'From'+from).digest('base64');const wrongMethod=await fetch(uri,{method:'GET'});rows.push({event:'sms-wrong-method',generation:g,status:wrongMethod.status,body:await wrongMethod.text()});assert.equal(wrongMethod.status,404);const wrongPath=await fetch(`http://127.0.0.1:${sms}/wrong-route`,{method:'POST',body:''});rows.push({event:'sms-wrong-path',generation:g,status:wrongPath.status,body:await wrongPath.text()});assert.equal(wrongPath.status,404);const response=await fetch(uri,{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded','x-twilio-signature':signature},body,signal:AbortSignal.timeout(20000)});const responseBody=await response.text();rows.push({event:'sms-inbound',generation:g,status:response.status,body:responseBody});assert.equal(response.status,200);}
